mapper.select:
SELECT stu.sid, stu.name, gra.grade, gra.grade_point, gra.course_name, gra.class_id, gra.year, gra.term, gra.credit, gra.teacher_name, gra.course_type FROM user stu LEFT JOIN score gra ON stu.sid = gra.sid
stu.sid LIKE CONCAT(#{sidPrefix}, '%') AND stu.major_name = #{majorName} AND gra.course_type = '必修'
AND gra.year = #{year}
